FAMILY = ("owner", "partner", "child")
# A party with a nest duck: below this (30%, where it stops walking) the family sets it back
# in its nest to charge.
PARTY_NEST_BATTERY = 3000


class Household:
    def __init__(self, seed: int) -> None:
        self.seed = seed
        self.counters: dict[str, int] = {}

    def _rand(self, purpose: str) -> int:
        counter = self.counters.get(purpose, 0) + 1
        self.counters[purpose] = counter
        return rng.draw(self.seed, "household-v1", purpose, counter)

    def _chance(self, purpose: str, probability: int) -> bool:
        return rng.below(self._rand(purpose), probability)

    def _pick(self, purpose: str, options: tuple[str, ...]) -> str:
        return options[rng.pick_index(self._rand(purpose), len(options))]

    def live(self, core: DuckCore, days: int, routine_id: str) -> dict[str, Any]:
        routine = ROUTINES[routine_id]
        days = max(1, min(int(days), 365))
        start_gd = core.s.gd
        start_events = len(core.log.events)
        milestones_before = {
            key for key, info in core.s.milestones.items() if info["status"] == "debuted"
        }
        if core.hw.nest:
            # A duck with a nest lives its own day between the visits: it charges in its nest,
            # sleeps there at night and wakes by itself at 07:00. Nobody switches it off or
            # plugs it in (that ran its own battery flat); it only goes back into its nest.
            self._to_nest(core, "owner")
        else:
            if routine.docked and not core.s.docked:
                core.set_setting("docked", True)
            if not routine.docked and core.s.docked:
                core.set_setting("docked", False)
            if core.s.awake and not routine.docked:
                core.power_off(None)
        first_day = core.s.now.date() + timedelta(days=1)
        for offset in range(days):
            day = first_day + timedelta(days=offset)
            if routine.weekdays is not None and day.weekday() not in routine.weekdays:
                continue
            if offset % routine.every_n_days:
                continue
            for hour, minute, duration in routine.visits:
                jitter = rng.pick_index(self._rand("jitter"), 31) - 15
                start = datetime(
                    day.year, day.month, day.day, hour, minute, tzinfo=core.s.now.tzinfo
                ) + timedelta(minutes=jitter)
                if start <= core.s.now:
                    continue
                core.advance(int((start - core.s.now).total_seconds() // 60))
                self._visit(core, routine, duration)
        end = datetime(
            first_day.year, first_day.month, first_day.day, tzinfo=core.s.now.tzinfo
        ) + timedelta(days=days)
        if end > core.s.now:
            core.advance(int((end - core.s.now).total_seconds() // 60))
        milestones_after = [
            info["title"]
            for key, info in sorted(core.s.milestones.items(), key=lambda item: item[1]["order"])
            if info["status"] == "debuted" and key not in milestones_before
        ]
        return {
            "routine": routine.zh,
            "days": days,
            "gd_from": start_gd,
            "gd_to": core.s.gd,
            "events": len(core.log.events) - start_events,
            "new_milestones": milestones_after,
        }

    def _to_nest(self, core: DuckCore, who: str, *, charge: bool = False) -> None:
        """A duck with a nest: back into it when it needs a hand (lifted, stuck, calling,
        switched off) or ``charge`` (its battery is low), where it charges even while
        switched off; switched off, it is switched on there."""
        s = core.s
        needs_hand = s.stranded is not None or s.unplaced or not s.awake or s.need is not None
        if not s.nested and (charge or needs_hand):
            core.place_on_nest(who)
        if not s.awake and s.nested:
            core.power_on(who)

    def _visit(self, core: DuckCore, routine: Routine, duration: int) -> None:
        owner_home = self._chance("owner_home", 7000)
        opener = "owner" if owner_home and self._chance("opener", 6000) else "partner"
        if core.hw.nest:
            self._to_nest(core, opener)
        elif not core.s.awake:
            core.power_on(opener)
        if routine.floor_p and self._chance("floor", routine.floor_p) and not core.s.floor:
            core.set_setting("floor", True)
        tv = self._chance("tv", 3000)
        if tv:
            core.tv(True)
        play_at = (
            12 + rng.pick_index(self._rand("play_at"), 8)
            if self._chance("play", routine.play_p)
            else -1
        )
        for minute in range(duration):
            if not core.s.awake:
                break
            if minute == 1 and owner_home and self._chance("hello", routine.hello_p):
                core.owner_hello()
            if minute == play_at:
                core.pad_play(
                    self._pick("player", FAMILY),
                    minutes=8 + rng.pick_index(self._rand("play_len"), 5),
                )
                continue
            flag = core.s.last_flag
            if (
                flag is not None
                and core.s.now - flag["at"] <= timedelta(seconds=3)
                and self._chance("praise", routine.praise_p)
            ):
                if owner_home and self._chance("praise_owner", 4000):
                    core.owner_good()
                else:
                    core.pad_good(self._pick("praiser", FAMILY))
            if self._chance("touch", routine.touch_p):
                who = self._pick("toucher", ("child", "child", "owner", "partner"))
                firmness = self._pick("firmness", ("light", "normal", "scratch"))
                core.touch(
                    who, seconds=3 + rng.pick_index(self._rand("touch_len"), 10), firmness=firmness
                )
            if self._chance("pickup", 300):
                picker = self._pick("picker", FAMILY)
                core.pickup(picker)  # being picked up ends floor mode…
                if routine.floor_p and self._chance("floor_again", routine.floor_p // 2):
                    core.set_setting("floor", True)  # …and sometimes they put it back down
                elif core.hw.nest:
                    core.place_on_nest(picker)  # …or, with a nest, back into it
            if core.hw.tof and self._chance("hand", 500):
                core.hand_near(
                    self._pick("hand", FAMILY),
                    speed="slow" if self._chance("slow", 8000) else "fast",
                )
            if self._chance("voice", 800):
                core.say(self._pick("speaker", FAMILY), kind="voice")
            self._minute_seen(core, routine, owner_home)
        if tv:
            core.tv(False)
        if core.hw.nest:
            # Bedtime for the visit: back into its nest to charge (never switched off).
            if not core.s.nested:
                core.place_on_nest(opener)
        elif core.s.awake and not core.s.docked:
            core.power_off(opener)

    def _minute_seen(self, core: DuckCore, routine: Routine, owner_home: bool) -> None:
        """Let the visit's minute pass, looking up a second after the duck's own moment in
        it: what it does falls anywhere in the minute (its beat), and praise only counts
        within 3 s, so a family that looked only at the minute's end could never praise."""
        s = core.s
        if s.awake and s.beat_s < 0:
            core.advance_seconds(1)  # the minute begins (and draws its beat)
        if s.awake and s.beat_s >= 0 and not s.beat_done and s.beat_s >= s.tick_s:
            core.advance_seconds(s.beat_s - s.tick_s + 1)
            flag = s.last_flag
            if (
                s.awake
                and flag is not None
                and s.now - flag["at"] <= timedelta(seconds=3)
                and self._chance("praise.beat", routine.praise_p)
            ):
                if owner_home and self._chance("praise_owner", 4000):
                    core.owner_good()
                else:
                    core.pad_good(self._pick("praiser", FAMILY))
            left = 60 - s.tick_s if s.tick_s else 0
            if left:
                core.advance_seconds(left)
            return
        core.advance(1)

    def party(self, core: DuckCore, *, guest_mode: bool) -> dict[str, Any]:
        """A birthday party: two hours of guests, children and noise."""

        s = core.s
        nest = core.hw.nest
        if nest:
            self._to_nest(core, "owner")
        elif not s.awake:
            core.power_on("owner")
        if guest_mode:
            core.pad_guest("owner")
        before = dict(s.care_window)
        touches = 0
        charged = 0
        for _ in range(120):
            if nest:
                # Its battery is its own: when it runs low (or someone lifted it and did not
                # put it down) the family sets it back in its nest to charge, and the party
                # goes on around it. A switched-off duck is switched on only there.
                low = s.battery < PARTY_NEST_BATTERY and not s.nested
                if low or s.unplaced or not s.awake:
                    charged += int(low)
                    self._to_nest(core, "owner", charge=low)
            elif not s.awake:
                core.power_on("owner")
            if self._chance("party.touch", 4000):
                core.touch(
                    self._pick("party.who", ("guest", "guest", "child", "child", "partner")),
                    seconds=4,
                )
                touches += 1
            # (Charging in its nest with little battery left, nobody lifts it out.)
            charging = nest and s.nested and s.battery < 2 * PARTY_NEST_BATTERY
            if self._chance("party.pick", 800) and not charging:
                core.pickup(self._pick("party.picker", ("guest", "child")))
                if nest and self._chance("party.set_down", 5000):
                    core.set_setting("floor", True)  # set down in front of its nest
            if self._chance("party.noise", 3000):
                core.say(None, kind="noise")
            core.advance(1)
        if nest and s.unplaced:
            core.place_on_nest("owner")  # the party is over: whoever holds it sets it home
        note = "每種照顧類型每個成長日最多只計 5 次；開了訪客模式就完全不計。"
        if charged:
            note += "電量低的時候，家人把牠放回窩裡充電，派對在旁邊照樣進行。"
        return {
            "touches": touches,
            "guest_mode": guest_mode,
            "care_before": before,
            "care_after": dict(s.care_window),
            "charged": charged,
            "note": note,
        }


