class _Draw:
    """The family's own counter-based stream (never the duck's)."""

    def __init__(self, seed: int, stream: str = "household-v2") -> None:
        self.seed, self.stream = seed, stream
        self.counters: dict[str, int] = {}

    def raw(self, purpose: str) -> int:
        counter = self.counters.get(purpose, 0) + 1
        self.counters[purpose] = counter
        return rng.draw(self.seed, self.stream, purpose, counter)

    def chance(self, purpose: str, probability: int) -> bool:
        return rng.below(self.raw(purpose), probability)

    def between(self, purpose: str, low: int, high: int) -> int:
        return low + rng.pick_index(self.raw(purpose), high - low + 1)

    def normal(self, purpose: str, mean: int, spread: int) -> int:
        """About N(mean, spread): three uniform integers added (deterministic)."""
        return mean + sum(self.between(purpose, -spread, spread) for _ in range(3)) * 10 // 17

    def pick(self, purpose: str, options: tuple[str, ...]) -> str:
        return options[rng.pick_index(self.raw(purpose), len(options))]


def make_profile(seed: int, kind: str | None = None) -> FamilyProfile:
    """One household, drawn from its seed (kind drawn from the mix unless given)."""
    d = _Draw(seed)
    if kind is None:
        kind = rng.pick_weighted(
            d.raw("kind"), {key: weight for key, (weight, _) in FAMILY_KINDS.items()}
        )
    if kind not in FAMILY_KINDS:
        raise ValueError(f"unknown family {kind}")
    low = kind == "low_attention"

    def member(role: str, persona: str, style: str) -> Member:
        base = CARE_STYLES[style]
        care = [max(2, value + d.between(f"care.{persona}", -8, 8)) for value in base]
        total = sum(care)
        care = [value * 100 // total for value in care]
        attentive = {
            "child": d.between("attentive", 6000, 9000),
            "elder": d.between("attentive", 5000, 8000),
        }.get(style, d.between("attentive", 4000, 8500))
        praise = {"child": 1500, "elder": 700}.get(style, 900)
        pickups = {"child": 3}.get(style, 1)
        react = {"child": 6000, "elder": 4500}.get(style, 3000)
        if low:
            attentive, praise, pickups = attentive * 3 // 10, praise // 5, 0
            react = react * 3 // 10
        favourites = tuple(
            FAVOURITES[rng.pick_index(d.raw(f"fav.{persona}"), len(FAVOURITES))] for _ in range(2)
        )
        return Member(
            role=role,
            persona=persona,
            care=(care[0], care[1], care[2], care[3]),
            attentive=attentive,
            react=react,
            praise=praise,
            pickups_per_day=pickups,
            phone=style != "child" and d.chance(f"phone.{persona}", 5000),
            favourites=favourites,
        )

    members: list[Member] = []
    wfh: frozenset[int] = frozenset()
    if kind in ("dual_income", "low_attention", "cable_only"):
        members = [member("worker", "owner", "adult"), member("worker", "partner", "adult")]
    elif kind == "school_family":
        partner_role = "wfh" if d.chance("partner_wfh", 3000) else "worker"
        members = [member("worker", "owner", "adult"), member(partner_role, "partner", "adult")]
        members.append(member("school_child", "child", "child"))
        if partner_role == "wfh":
            wfh = frozenset(range(5))
    elif kind == "hybrid":
        days = d.between("wfh_n", 2, 3)
        order = [0, 1, 2, 3, 4]
        chosen: list[int] = []
        for _ in range(days):
            chosen.append(order.pop(rng.pick_index(d.raw("wfh_day"), len(order))))
        wfh = frozenset(chosen)
        members = [member("wfh", "owner", "adult")]
        if d.chance("hybrid_partner", 5000):
            members.append(member("worker", "partner", "adult"))
    elif kind == "elder_home":
        members = [member("elder", "elder", "elder")]
        if d.chance("three_gen", 5000):
            members += [
                member("worker", "owner", "adult"),
                member("school_child", "child", "child"),
            ]
    elif kind == "single_long":
        members = [member("worker", "owner", "adult")]
    elif kind == "shift":
        members = [member("shift", "owner", "adult")]
        if d.chance("shift_partner", 5000):
            members.append(member("worker", "partner", "adult"))
    roam = rng.pick_weighted(d.raw("roam"), {"1500": 6, "2000": 2, "1000": 1, "2750": 1})
    trips = tuple(
        (d.between("trip.day", 20, 350), d.between("trip.len", 2, 7))
        for _ in range(d.between("trips", 0, 3))
    )
    change = d.chance("change", 2000)
    cable = kind == "cable_only"
    camera = not cable and d.chance("camera", 9000)
    return FamilyProfile(
        kind=kind,
        zh=FAMILY_KINDS[kind][1],
        members=tuple(members),
        wfh_days=wfh,
        roam_radius_mm=int(roam),
        app_buttons=d.chance("app", 3000),
        goodnight=d.chance("goodnight", 6000),
        tv_hours=d.between("tv", 0, 4),
        nest=not cable,
        cable=cable,
        camera=camera,
        tof=d.chance("tof", 3000),
        ear=d.chance("ear", 9000),
        name_ear=d.chance("name_ear", 8000),
        wake_min=420,
        change_day=d.between("change_day", 90, 270) if change else None,
        change_to=d.pick("change_to", ("wfh", "baby", "move")) if change else None,
        low_care=low,
        conservative_end_gd=None if d.chance("cons_never", 1000) else d.between("cons_end", 14, 30),
        trips=trips,
    )


@dataclass(slots=True)
class _Person:
    member: Member
    wake: int = 420
    bed: int = 1380
    away: list[tuple[int, int]] = field(default_factory=list)
    in_room: bool = False
    room_until: int = -1


class HouseholdV2:
    """A simulated family (spec chapter 10). ``truth`` is the simulator's ground truth of
    who was home and awake (never the duck's memory)."""

    def __init__(self, seed: int, profile: FamilyProfile) -> None:
        self.seed = seed
        self.profile = profile
        self.d = _Draw(seed, "household-v2.day")
        self.truth: list[tuple[str, int, int, int]] = []
        self.days_lived = 0
        self.stats: dict[str, int] = {}
        self._forgotten_until: datetime | None = None
        self._off_noticed: datetime | None = None
        self._hello = False
        self._tv_on_at = -1
        self._goodnight_done = False
        # A call for attention someone will answer: (when it was made, when, who, how).
        self._bid_plan: tuple[datetime, datetime, str, int] | None = None
        self._bid_seen: datetime | None = None
        self._moment_seen: str | None = None

    # -------------------------------------------------------------------- setting up

    def _setup(self, core: DuckCore) -> None:
        p = self.profile
        if p.cable and not core.s.docked:
            core.set_setting("docked", True)
            if not core.s.floor:
                core.set_setting("floor", True)
        if core.hw.nest and core.s.roam_radius_mm != p.roam_radius_mm:
            core.set_roam_radius(p.roam_radius_mm)
        if core.s.battery_help:
            core.set_setting("battery_help", False)

    # -------------------------------------------------------------------- the family's day

    def _plan(self, day: date, index: int) -> list[_Person]:
        p = self.profile
        d = self.d
        members = list(p.members)
        if p.change_day is not None and index >= p.change_day and p.change_to == "wfh":
            members = [
                replace(m, role="wfh") if m.role == "worker" else m for m in members[:1]
            ] + members[1:]
        weekend = day.weekday() >= 5 or (day.month, day.day) in HOLIDAYS
        school_break = (
            day.month in (7, 8)
            or (day.month == 1 and day.day >= 20)
            or (day.month == 2 and day.day <= 15)
        )
        trip = any(start <= index < start + length for start, length in p.trips)
        spring = day.month == 2 and 5 <= day.day <= 11 and p.change_to != "move"
        people: list[_Person] = []
        outings: list[tuple[int, int]] = []
        if weekend and not trip and d.chance("weekend_out", 6000):
            for _ in range(d.between("weekend_outs", 1, 2)):
                start = d.between("out_start", 540, 1020)
                outings.append((start, min(1320, start + d.between("out_len", 60, 300))))
        sick = not weekend and d.chance("sick", 300)
        irregular = d.chance("irregular", 1000)
        spread = 2 if irregular else 1
        for m in members:
            person = _Person(m)
            if m.role == "school_child":
                person.wake, person.bed = d.normal("wake", 400, 15), d.between("bed", 1230, 1290)
            elif m.role == "elder":
                person.wake, person.bed = d.normal("wake", 360, 30), d.normal("bed", 1290, 30)
            else:
                person.wake = d.normal("wake", 405, 25 * spread)
                person.bed = min(1439, d.normal("bed", 1365, 35))
            if weekend:
                person.wake = max(person.wake, d.normal("wake_we", 510, 60))
                person.bed = min(1439, person.bed + 30)
            if trip:
                person.away = [(0, 1440)]
                people.append(person)
                continue
            away: list[tuple[int, int]] = []
            if m.role == "shift" and not weekend:
                person.wake, person.bed = 900, 1439
                away = [(0, 450), (1260, 1440)]
            elif m.role == "worker" and not weekend and not (sick and m.persona == "owner"):
                leave, back = (
                    d.normal("leave", 470, 25 * spread),
                    d.normal("back", 1110, 60 * spread),
                )
                if p.kind == "school_family":
                    leave, back = d.normal("leave", 480, 20), d.normal("back", 1080, 45)
                elif p.kind == "single_long":
                    leave, back = d.normal("leave", 450, 20), d.normal("back", 1200, 45)
                leave = max(person.wake + 20, leave)
                away = [(leave, max(leave + 120, back))]
            elif (
                m.role == "wfh"
                and not weekend
                and day.weekday() not in p.wfh_days
                and p.kind == "hybrid"
            ):
                leave, back = d.normal("leave", 470, 25), d.normal("back", 1110, 60)
                away = [(max(person.wake + 20, leave), back)]
            elif m.role == "school_child" and not weekend and not school_break:
                leave = d.normal("leave", 435, 10)
                away = [(max(person.wake + 15, leave), d.between("back", 960, 1050))]
            elif m.role in ("elder", "wfh") and d.chance("errand", 5000):
                start = d.between("errand_at", 540, 900)
                away = [(start, start + d.between("errand_len", 30, 180))]
            if spring and d.chance("spring_guests", 6000):
                away = []
            person.away = sorted(away + outings)
            people.append(person)
        return people

    @staticmethod
    def _state(person: _Person, minute: int) -> str:
        if any(start <= minute < end for start, end in person.away):
            return "away"
        if minute < person.wake or minute >= person.bed:
            return "asleep"
        return "home"

    # -------------------------------------------------------------------- living

    def live(self, core: DuckCore, days: int) -> dict[str, Any]:
        days = max(1, min(int(days), 400))
        start_gd, start_events = core.s.gd, len(core.log.events)
        milestones_before = {
            key for key, info in core.s.milestones.items() if info["status"] == "debuted"
        }
        self._setup(core)
        tz = core.s.now.tzinfo
        first = core.s.now.date()
        end = datetime.combine(first + timedelta(days=days), time(0), tz)
        today: date | None = None
        people: list[_Person] = []
        states: dict[int, str] = {}
        while core.s.now < end:
            now = core.s.now
            if now.date() != today:
                today = now.date()
                index = self.days_lived
                self.days_lived += 1
                people = self._plan(today, index)
                self._daily(core, index)
                self._tv_on_at = (
                    1140 + self.d.between("tv_at", 0, 60) if self.profile.tv_hours else -1
                )
                self._goodnight_done = False
            minute = now.hour * 60 + now.minute
            for i, person in enumerate(people):
                state = self._state(person, minute)
                before = states.get(i)
                if state != before:
                    states[i] = state
                    self._transition(core, person, before, state, people, minute)
            home = [person for i, person in enumerate(people) if states.get(i) == "home"]
            self._record_truth(core, people, states)
            if not home:
                step = self._next_change(people, minute, states)
                target = min(end, datetime.combine(today, time(0), tz) + timedelta(minutes=step))
                gap = int((target - core.s.now).total_seconds())
                if gap <= 0:
                    gap = 60
                core.advance_seconds(gap)
                continue
            self._minute(core, home, minute)
        return {
            "family": self.profile.zh,
            "routine": self.profile.zh,
            "kind": self.profile.kind,
            "days": days,
            "gd_from": start_gd,
            "gd_to": core.s.gd,
            "events": len(core.log.events) - start_events,
            "new_milestones": [
                info["title"]
                for key, info in sorted(
                    core.s.milestones.items(), key=lambda item: item[1]["order"]
                )
                if info["status"] == "debuted" and key not in milestones_before
            ],
        }

    def _next_change(self, people: list[_Person], minute: int, states: dict[int, str]) -> int:
        """The next minute of the day someone gets up, leaves or comes home (≤ midnight)."""
        points = [1440]
        for person in people:
            for moment in (person.wake, person.bed, *[x for span in person.away for x in span]):
                if moment > minute:
                    points.append(moment)
        return max(minute + 1, min(points))

    def _record_truth(self, core: DuckCore, people: list[_Person], states: dict[int, str]) -> None:
        home = sum(1 for i in range(len(people)) if states.get(i) == "home")
        room = sum(1 for i, p in enumerate(people) if states.get(i) == "home" and p.in_room)
        asleep = sum(1 for i in range(len(people)) if states.get(i) == "asleep")
        row = (core.s.now.isoformat(timespec="minutes"), home, room, asleep)
        if not self.truth or self.truth[-1][1:] != row[1:]:
            self.truth.append(row)

    def _daily(self, core: DuckCore, index: int) -> None:
        p = self.profile
        if (
            p.conservative_end_gd is not None
            and core.s.conservative
            and core.s.gd >= p.conservative_end_gd
        ):
            core.set_setting("conservative", False)
        if p.change_day is not None and index == p.change_day and p.change_to == "move":
            if core.hw.nest:
                core.nest_moved()

    def _transition(
        self,
        core: DuckCore,
        person: _Person,
        before: str | None,
        state: str,
        people: list[_Person],
        minute: int,
    ) -> None:
        d = self.d
        persona = person.member.persona
        if before is None:
            return  # the day's first look: nothing happened just now
        if state == "away":
            person.in_room = False
            if d.chance("door_seen", 9000):
                core.hear_home(persona, kind="door", journal=False)
            if person.member.phone:
                core.hear_home(persona, kind="phone_out", journal=False)
            others_home = [
                p for p in people if p is not person and self._state(p, minute) == "home"
            ]
            if not others_home:
                duck = core.s
                # The last one out looks at the duck: off the nest and stuck, back it goes.
                if (
                    core.hw.nest
                    and not duck.nested
                    and (
                        duck.unplaced
                        or duck.stranded is not None
                        or not duck.awake
                        or duck.battery < 4500
                    )
                    and (duck.need is not None or d.chance("leaving_check", 8000))
                ):
                    self._forgotten_until = None
                    core.place_on_nest(persona)
                if self.profile.app_buttons and d.chance("app_leave", 7000):
                    core.family_leave()
        elif before == "away" and state in ("home", "asleep"):
            if d.chance("door_seen", 9000):
                core.hear_home(persona, kind="door", journal=False)
            core.hear_home(persona, kind="voice", journal=False)
            if person.member.phone:
                core.hear_home(persona, kind="phone_in", journal=False)
            others_home = [
                p for p in people if p is not person and self._state(p, minute) == "home"
            ]
            if not others_home and self.profile.app_buttons and d.chance("app_back", 7000):
                core.family_return()
            if persona == "owner" and d.chance("hello", 6000):
                self._hello = True
        elif before == "asleep" and state == "home":
            core.hear_home(persona, kind="steps", journal=False)

    def _minute(self, core: DuckCore, home: list[_Person], minute: int) -> None:
        """One minute with someone home and awake: cues, company, care, answers."""
        d = self.d
        s = core.s
        p = self.profile
        low = p.low_care
        for person in home:
            if minute >= person.room_until:
                evening = minute >= 1020
                share = 5500 if evening else 3500 if minute < 540 else 3000
                if person.member.role in ("elder", "school_child"):
                    share += 1500
                if low:
                    share = share * 3 // 10
                person.in_room = d.chance("room", share)
                person.room_until = minute + d.between("room_len", 10, 40)
        room = [person for person in home if person.in_room]
        for person in home:
            persona = person.member.persona
            if person.in_room:
                if d.chance("cue.voice", 3000):
                    core.hear_home(persona, kind="voice", journal=False)
                if p.camera and d.chance("cue.person", 5000):
                    core.hear_home(persona, kind="person", journal=False)
            elif d.chance("cue.far", 1500):
                core.hear_home(
                    persona, kind="voice" if d.chance("far_kind", 5000) else "steps", journal=False
                )
        if self._tv_on_at >= 0:
            if minute == self._tv_on_at and not s.tv_on:
                core.tv(True)
            elif s.tv_on and minute >= self._tv_on_at + 60 * p.tv_hours:
                core.tv(False)
        if s.tv_on and d.chance("cue.tv", 5000):
            core.hear_home(None, kind="tv_voice", journal=False)
        if (
            p.goodnight
            and not self._goodnight_done
            and 1265 <= minute < 1290
            and d.chance("goodnight", 2500)
        ):
            self._goodnight_done = True
            core.goodnight(home[0].member.persona)
        self._look_after(core, home, room, minute)
        self._plan_answer(core, home, room)
        if not room:
            self._step(core, 60, [])
            return
        self._care_minute(core, room, minute)
        self._step(core, 60, room)

    def _step(self, core: DuckCore, seconds: int, room: list[_Person]) -> None:
        """Let a minute pass, stopping a second after each thing the duck does by itself
        (its decision beat, the end of a leg) so the family can praise it in time, and when
        a planned answer to its call is due."""
        s = core.s
        end = s.now + timedelta(seconds=seconds)
        for _ in range(8):
            if s.now >= end:
                return
            points = [end]
            if room and s.awake:
                if s.beat_s >= 0 and not s.beat_done and s.beat_s >= s.tick_s:
                    points.append(s.now + timedelta(seconds=s.beat_s - s.tick_s + 1))
                due = core._stand_due()
                if due is not None and due > s.now:
                    points.append(due + timedelta(seconds=1))
            if self._bid_plan is not None and self._bid_plan[1] > s.now:
                points.append(self._bid_plan[1])
            target = min(point for point in points if point > s.now)
            core.advance_seconds(max(1, int((min(target, end) - s.now).total_seconds())))
            self._answer(core, room)
        if s.now < end:
            core.advance_seconds(int((end - s.now).total_seconds()))
            self._answer(core, room)

    def _plan_answer(self, core: DuckCore, home: list[_Person], room: list[_Person]) -> None:
        """A new call for attention: whoever hears it decides whether (and when) to answer."""
        d = self.d
        since = core.s.bid_pending_since
        if since is None or since == self._bid_seen:
            return
        self._bid_seen = since
        for person in room + [p for p in home if p not in room]:
            chance = person.member.attentive if person in room else person.member.attentive // 2
            if d.chance("answer", chance):
                delay = d.between("answer_s", 3, 75)
                how = d.between("answer_how", 1, 3)
                self._bid_plan = (
                    since,
                    since + timedelta(seconds=delay),
                    person.member.persona,
                    how,
                )
                return

    def _look_after(
        self, core: DuckCore, home: list[_Person], room: list[_Person], minute: int
    ) -> None:
        """What a family does about a duck that needs a hand (placed, set upright…)."""
        d = self.d
        s = core.s
        see = 3000 if room else 800
        if s.need is not None:
            see = 6000 if room else 2500  # it is calling for help: they hear it
        who = (room or home)[0].member.persona
        if not s.awake:
            if s.nested or s.docked:
                if self._off_noticed is None:
                    self._off_noticed = s.now
                elif s.now - self._off_noticed >= timedelta(minutes=30):
                    core.power_on(who)
                    self._off_noticed = None
            elif d.chance("see_off", see):
                if core.hw.nest:
                    core.place_on_nest(who)
                else:
                    core.set_setting("docked", True)
                self._off_noticed = s.now
            return
        if self._forgotten_until is not None:
            if s.now >= self._forgotten_until or (
                s.need is not None and d.chance("hear_need", see)
            ):
                self._forgotten_until = None
                self._place(core, who)
            return
        if s.posture == "fallen" and s.righting is None and d.chance("see_fallen", see):
            core.set_upright(who)
            self.stats["set_upright"] = self.stats.get("set_upright", 0) + 1
            return
        if (
            s.stranded is not None or s.unplaced or (s.need or {}).get("kind") == "nest_help"
        ) and d.chance("see_need", see):
            self._place(core, who)
            self.stats["helped"] = self.stats.get("helped", 0) + 1

    def _place(self, core: DuckCore, who: str) -> None:
        if core.hw.nest:
            core.place_on_nest(who)
        elif not core.s.floor:
            core.set_setting("floor", True)

    def _care_minute(self, core: DuckCore, room: list[_Person], minute: int) -> None:
        d = self.d
        s = core.s
        for person in room:
            m = person.member
            persona = m.persona
            talk, touch, play, calm = m.care
            scale = 3 if self.profile.low_care else 10
            if self._hello and persona == "owner":
                self._hello = False
                core.owner_hello()
                continue
            if d.chance("talk", talk * 12 * scale // 10):
                if s.awake and core.hw.name_ear and d.chance("by_name", 3500):
                    core.call_name(persona)
                else:
                    core.say(persona, kind="voice")
            if d.chance("touch", touch * 10 * scale // 10):
                core.touch(
                    persona,
                    seconds=d.between("touch_s", 3, 12),
                    firmness=d.pick("firmness", ("light", "normal", "scratch")),
                )
            if (
                play
                and s.awake
                and not s.yielding
                and s.battery >= 6000
                and minute < 1260
                and d.chance(
                    "pad_play", play * 3 * scale // 10 // (1 if m.role == "school_child" else 2)
                )
            ):
                core.pad_play(persona, minutes=d.between("play_len", 5, 12))
                if core.hw.nest and s.awake and not s.nested and s.battery < 4500:
                    core.place_on_nest(persona)  # tired of playing: back to its nest
            if (
                m.pickups_per_day
                and s.awake
                and not core._until(s.napping_until)
                and d.chance("pickup", m.pickups_per_day * 10000 // 200)
            ):
                core.pickup(persona)
                where = d.between("put", 1, 100)
                if core.hw.nest and (
                    "wander" not in s.unlocked or s.battery < 4500 or minute >= 1230
                ):
                    where = 1  # a duck that cannot walk far (or at bedtime) goes to its nest
                if where <= 60:
                    core.place_on_nest(persona) if core.hw.nest else core.set_setting("floor", True)
                elif where <= 85:
                    core.set_setting("floor", True)
                else:
                    self._forgotten_until = s.now + timedelta(minutes=d.between("forgot", 10, 120))
            del calm

    def _answer(self, core: DuckCore, room: list[_Person]) -> None:
        """Answers in time: a call for attention within 90 s, praise within 3 s."""
        d = self.d
        s = core.s
        if not s.awake:
            return
        plan = self._bid_plan
        if plan is not None and s.now >= plan[1]:
            self._bid_plan = None
            if s.bid_pending_since == plan[0]:
                persona, how = plan[2], plan[3]
                if how == 1:
                    core.touch(persona, seconds=d.between("touch_s", 3, 8))
                elif how == 2 and core.hw.name_ear:
                    core.call_name(persona)
                else:
                    core.say(persona, kind="voice")
                self.stats["answered"] = self.stats.get("answered", 0) + 1
        flag = s.last_flag
        if flag is not None and s.now - flag["at"] <= timedelta(seconds=3):
            for person in room:
                liked = str(flag.get("id")) in person.member.favourites
                chance = person.member.praise * (2 if liked else 1) // 2
                if d.chance("praise", chance):
                    if person.member.persona == "owner" and d.chance("praise_phone", 4000):
                        core.owner_good()
                    else:
                        core.pad_good(person.member.persona)
                    break
        moment = s.last_moment
        if (
            moment is not None
            and not moment.get("seen")
            and moment.get("event") != self._moment_seen
            and s.now - moment["at"] <= timedelta(seconds=10)
        ):
            # Someone in the room saw it do something clever or goofy: they may react
            # (a laugh and a word, a pat, a 乖) within the ten seconds it notices that in.
            self._moment_seen = str(moment.get("event"))
            for person in room:
                if d.chance("react", person.member.react):
                    persona = person.member.persona
                    how = d.between("react_how", 1, 3)
                    if how == 1:
                        core.touch(persona, seconds=d.between("touch_s", 2, 6))
                    elif how == 2:
                        core.pad_good(persona)
                    else:
                        core.say(persona, kind="voice")
                    self.stats["reacted"] = self.stats.get("reacted", 0) + 1
                    break
